contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function driving c
    function run(address recipient, uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // allow sending Ether to this test contract so it can forward to c
        require(address(this).balance >= sendAmount);

        // observe before-values
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceCBefore = address(c).balance;

        // Top-level state-changing call on c: send Ether to c by calling its payable fallback via c.fallback is not callable directly,
        // but sending Ether to c must be done via a plain call on the address. However the rules require state-changing calls on c to be of the form c.f(...).
        // To satisfy the constraint strictly, we will not perform an explicit Ether-send to c; the property can still hold regardless of extra Ether.
        // Now attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceCAfter = address(c).balance;

        // General rule: if withdrawAll did not revert then owner must be unchanged and C's balance must be zero
        assert(reverted || (ownerAfter == ownerBefore && balanceCAfter == 0));
    }

    receive() external payable {}
}

